python3 << 'EOF'
import csv
from collections import Counter, defaultdict

with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    rows = list(reader)

# Prepare decade data for chart
decade_data = {}
for row in rows:
    year = int(row['Year'])
    decade = (year // 10) * 10
    if decade not in decade_data:
        decade_data[decade] = {'years': 0, 'composers': set(), 'repeat': 0, 'new': 0}
    decade_data[decade]['years'] += 1
    composers = [c.strip() for c in row['Composer'].split(',')]
    decade_data[decade]['composers'].update(composers)

# Mark repeat vs new
composer_wins = Counter()
for row in rows:
    year = int(row['Year'])
    decade = (year // 10) * 10
    composers = [c.strip() for c in row['Composer'].split(',')]
    had_won = any(composer_wins[c] > 0 for c in composers)
    if had_won:
        decade_data[decade]['repeat'] += 1
    else:
        decade_data[decade]['new'] += 1
    for c in composers:
        composer_wins[c] += 1

for decade in sorted(decade_data.keys()):
    d = decade_data[decade]
    print(f"{decade}s: {d['years']} ceremonies, {len(d['composers'])} unique composers, {d['repeat']} repeat, {d['new']} new")

# Era dominant composers with films
eras = {
    'Golden Age': (1934, 1959),
    'Silver Age': (1960, 1979),
    'Modern Era': (1980, 1999),
    'Contemporary Era': (2000, 2026)
}

for era_name, (start, end) in eras.items():
    era_composer_wins = Counter()
    era_composer_films = defaultdict(list)
    for row in rows:
        year = int(row['Year'])
        if start <= year <= end:
            composers = [c.strip() for c in row['Composer'].split(',')]
            for c in composers:
                era_composer_wins[c] += 1
                era_composer_films[c].append((year, row['Film']))
    print(f"\n{era_name}:")
    for c, w in era_composer_wins.most_common(5):
        print(f"  {c}: {w} wins - {era_composer_films[c]}")

