python3 << 'EOF'
import csv
from collections import Counter, defaultdict

with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    rows = list(reader)

# Count all composers by era for stacked bar
eras = {
    'Golden Age': (1934, 1959),
    'Silver Age': (1960, 1979),
    'Modern Era': (1980, 1999),
    'Contemporary Era': (2000, 2026)
}

era_composer_wins = {}
for era_name, (start, end) in eras.items():
    era_composer_wins[era_name] = Counter()
    for row in rows:
        year = int(row['Year'])
        if start <= year <= end:
            composers = [c.strip() for c in row['Composer'].split(',')]
            for c in composers:
                era_composer_wins[era_name][c] += 1

print("Era composer wins (all):")
for era, counter in era_composer_wins.items():
    print(f"\n{era}:")
    for c, w in counter.most_common():
        print(f"  {c}: {w}")

# Timeline data for all years
print("\n\nAll years for timeline:")
for row in rows:
    print(f"  {row['Year']}: {row['Composer']} - {row['Film']}")

